import { describe, expect, it } from "vitest";
import vectors from "../../../test-vectors/app_compose_hash.json";
import { dumpAppCompose, getComposeHash, preprocessAppCompose, type AppCompose } from "./get_compose_hash";

// Shared vectors generated by the Phala Cloud backend (see the file's _comment).
// The Python and Go SDKs assert the same file.
describe("getComposeHash matches the backend", () => {
  for (const vector of vectors.cases) {
    it(`${vector.name}: canonical bytes and sha256`, () => {
      const compose = vector.input as unknown as AppCompose;
      expect(dumpAppCompose(preprocessAppCompose(compose))).toBe(vector.canonical);
      expect(getComposeHash(compose)).toBe(vector.hash);
    });
  }

  it("does not escape non-ASCII or HTML characters", () => {
    const dumped = dumpAppCompose({ name: "日本語 <&>" });
    expect(dumped).toBe('{"name":"日本語 <&>"}');
  });
});
